//! ```compile_fail
//! use verter_span::{SourceByteOffset, SourceByteRange};
//!
//! let _ = SourceByteRange { start: SourceByteOffset::new(5), end: SourceByteOffset::new(3) }; // no struct literal
//! ```

use std::fmt;

/// The typed failure vocabulary of the checked coordinate API (the case
/// table's `errorVocabulary`): every refusal names one of these, and nothing
/// clamps, saturates, wraps or snaps instead.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CoordError {
    /// The offset or range is outside its domain's extent in the content it
    /// was checked against, or a range is inverted. Never normalised: an
    /// inverted range is not swapped or emptied, a past-end offset is not
    /// clamped to end-of-file.
    InvalidBoundary,
    /// Checked arithmetic left the `u32` width (overflow or underflow). Never
    /// saturated or wrapped.
    Overflow,
    /// The offset lands inside a UTF-8 sequence, or a requester offset lands
    /// inside a surrogate pair. Never snapped to the nearest boundary.
    NotCharBoundary,
}

impl fmt::Display for CoordError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            CoordError::InvalidBoundary => {
                f.write_str("coordinate is outside its content extent or inverted")
            }
            CoordError::Overflow => f.write_str("checked coordinate arithmetic left u32"),
            CoordError::NotCharBoundary => {
                f.write_str("coordinate does not land on a character boundary")
            }
        }
    }
}

impl std::error::Error for CoordError {}

/// Defines one coordinate domain: a `#[repr(transparent)]` byte-offset newtype
/// plus its `#[repr(C)]` half-open range, with the same checked surface for
/// every domain (only the domain differs — never the operations).
macro_rules! coord_domain {
    (
        $(#[$offset_doc:meta])*
        $offset:ident,
        $(#[$range_doc:meta])*
        $range:ident
    ) => {
        $(#[$offset_doc])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        #[repr(transparent)]
        pub struct $offset(pub u32);

        impl $offset {
            /// The explicit named constructor from a raw byte offset. Together
            /// with the tuple form (kept for existing callers) this is the only
            /// raw-integer entry point; no `From<u32>`, `Deref` or `Add<u32>`
            /// exists.
            #[inline]
            pub const fn new(offset: u32) -> Self {
                Self(offset)
            }

            /// The raw UTF-8 byte offset.
            #[inline]
            pub const fn get(self) -> u32 {
                self.0
            }

            /// Advance by `len` bytes (the relative-to-absolute rebase is
            /// `base.checked_add(relative)`), refusing to leave the `u32`
            /// width with [`CoordError::Overflow`].
            #[inline]
            pub fn checked_add(self, len: u32) -> Result<Self, CoordError> {
                self.0
                    .checked_add(len)
                    .map(Self)
                    .ok_or(CoordError::Overflow)
            }

            /// Rebase below `base`, where both offsets are of this one
            /// domain. The answer is a base-relative byte length — the
            /// same unit [`Self::checked_add`] takes — never an absolute
            /// offset of this domain: `self - base` names no position in
            /// the content, so minting it as one would let a relative
            /// amount flow into absolute-position consumers
            /// (`validate`, `line_col`, range construction) unchecked.
            /// A base greater than the offset is
            /// [`CoordError::Overflow`] — refused, never wrapped or
            /// saturated.
            #[inline]
            pub fn checked_sub(self, base: Self) -> Result<u32, CoordError> {
                self.0.checked_sub(base.0).ok_or(CoordError::Overflow)
            }

            /// Check this offset against the exact content snapshot it
            /// indexes: past the end is [`CoordError::InvalidBoundary`]
            /// (end-of-file itself is valid), inside a UTF-8 sequence is
            /// [`CoordError::NotCharBoundary`]. Never clamped or snapped.
            pub fn validate(self, content: &str) -> Result<Self, CoordError> {
                let raw = self.0 as usize;
                if raw > content.len() {
                    return Err(CoordError::InvalidBoundary);
                }
                if !content.is_char_boundary(raw) {
                    return Err(CoordError::NotCharBoundary);
                }
                Ok(self)
            }
        }

        $(#[$range_doc])*
        /// An inverted range (`end < start`) is not constructible: the
        /// ordered invariant is enforced at construction, so no method has
        /// to normalise one. The endpoints are private, so no safe code can
        /// assemble a range or write one endpoint past the other; they are
        /// read through [`Self::start`] and [`Self::end`].
        #[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
        #[repr(C)]
        pub struct $range {
            start: $offset,
            end: $offset,
        }

        impl $range {
            /// Construct from already-ordered offsets. An inverted range
            /// (`end < start`) is refused loudly here — never swapped or
            /// emptied; [`Self::checked_new`] is the form that answers the
            /// refusal as a value.
            ///
            /// # Panics
            ///
            /// When `end < start`.
            #[inline]
            pub const fn new(start: $offset, end: $offset) -> Self {
                assert!(
                    start.0 <= end.0,
                    "a byte range is ordered: end < start is refused, not normalised"
                );
                Self { start, end }
            }

            /// Construct, refusing an inverted range: `end < start` is
            /// [`CoordError::InvalidBoundary`] — never swapped or emptied.
            #[inline]
            pub fn checked_new(start: $offset, end: $offset) -> Result<Self, CoordError> {
                if end.0 < start.0 {
                    return Err(CoordError::InvalidBoundary);
                }
                Ok(Self { start, end })
            }

            /// Inclusive start, in this domain's bytes.
            #[inline]
            pub const fn start(&self) -> $offset {
                self.start
            }

            /// Exclusive end, in this domain's bytes.
            #[inline]
            pub const fn end(&self) -> $offset {
                self.end
            }

            /// Length in this domain's bytes. Total for every constructible
            /// range: `new` and `checked_new` refuse inversion, and the
            /// endpoints are private, so the subtraction never saturates or
            /// wraps.
            #[inline]
            pub const fn len(&self) -> u32 {
                self.end.0 - self.start.0
            }

            #[inline]
            pub const fn is_empty(&self) -> bool {
                self.start.0 == self.end.0
            }

            /// Check both endpoints against the exact content snapshot:
            /// inverted or past-the-end is [`CoordError::InvalidBoundary`]; an
            /// endpoint inside a UTF-8 sequence is
            /// [`CoordError::NotCharBoundary`]. An empty range at offset 0 or
            /// at end-of-file is valid.
            pub fn validate(&self, content: &str) -> Result<Self, CoordError> {
                if self.end.0 < self.start.0 {
                    return Err(CoordError::InvalidBoundary);
                }
                self.start.validate(content)?;
                self.end.validate(content)?;
                Ok(*self)
            }
        }
    };
}

coord_domain! {
    /// Byte offset into the source coordinate domain (`CD1`): UTF-8 bytes from
    /// the start of an authored file (carrier or plain module).
    SourceByteOffset,
    /// Half-open `[start, end)` byte range in the source coordinate domain
    /// (`CD1`).
    SourceByteRange
}

coord_domain! {
    /// Byte offset into the generated coordinate domain (`CD3`): UTF-8 bytes
    /// from the start of one generated surface (IDE TSX, compiled output,
    /// companion).
    GeneratedByteOffset,
    /// Half-open `[start, end)` byte range in the generated coordinate domain
    /// (`CD3`).
    GeneratedByteRange
}

coord_domain! {
    /// Byte offset into the embedded coordinate domain (`CD4`): UTF-8 bytes
    /// into the cooked or derived text of a region whose bytes are not its
    /// authored bytes.
    EmbeddedByteOffset,
    /// Half-open `[start, end)` byte range in the embedded coordinate domain
    /// (`CD4`).
    EmbeddedByteRange
}

/// Length in bytes of a generated-surface content region (the
/// `content_offset` domain of `CD3`). A length carries no position, so it has
/// no checked-conversion surface.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[repr(transparent)]
pub struct GeneratedByteLen(pub u32);

